export function buildSecTenderAnalysisPromptDraft(input: SecTenderAnalysisPromptInput) {
  return {
    key: SEC_TENDER_ANALYSIS_PROMPT_KEY,
    version: SEC_TENDER_ANALYSIS_PROMPT_VERSION,
    system: secTenderAnalysisSystemPrompt,
    user: JSON.stringify({
      ...buildSecTenderSourceBlockPromptInput({
        filingPackage: input.filing_package,
        parserOutput: input.parser_output,
        fallbackText: input.filing_excerpt,
        parentFilingContext: input.parent_filing_context,
      }),
      filing_context: input.filing_context || null,
      parent_filing_context: input.parent_filing_context || null,
      market_context: input.market_context || null,
    }),
    responseFormat: {
      type: "json_schema",
      json_schema: {
        name: "sec_tender_cb_13e3_required_output",
        strict: true,
        schema: secTenderRequiredOutputSchema,
      },
    },
  };
}
